import type { Elements, RenderElement } from 'claude-code'

import { bytes, middle, money, short, tokens } from '../kit/format'
import type { PerfSnapshot } from '../kit/perf'
import { C, GLYPH, GRAY, INK, MUTED, RAMP, TRACK, levelColor } from '../kit/tokens'
import { EDGE, SPACE, kit } from '../kit/ui'

import type { Activity, Agent, AgentExtra, BranchView, Doing, GhInfo, GitInfo, GitNote, GitPr, Limit, Resources, Snapshot, WorkspacesGh } from '../types'

/*
 * The app mode: a properties inspector for the session, drawn as an instrument.
 *
 * The rules it keeps (kit/tokens.ts and kit/ui.tsx hold the values):
 * - Colour: each hue one meaning (grey labels, slate quantity, blue live, amber
 *   near a limit, red failed, green done well, purple merged). Icons are muted.
 * - Type: values plain, labels and units dim, bold only for section titles and
 *   the context %, uppercase only for captions and a branch's state word.
 * - Spacing: the kit's SPACE scale and INSET; nothing else.
 * - Each fact once: calls and time in the header, cost in Accounting.
 */

/** The elements the app mode draws with: the desktop and VS Code have these. */
export type AppElements = Pick<Elements['desktop'], 'Box' | 'Text' | 'Link' | 'Button' | 'Svg'>

export type DesktopData = {
  snap: Snapshot | null
  limits: Limit[] | null
  agents: Agent[]
  extras: Record<string, AgentExtra>
  git: GitInfo | GitNote | null
  gh: GhInfo | null
  activity: Activity
  /** Section ids the person folded. */
  collapsed: string[]
  /** Folds or unfolds a section. */
  toggle: (id: string) => void
  /** The column view's switch: on, a wide pane flows its sections into columns. */
  columnsOn: boolean
  /** Flips the column view. */
  toggleColumns: () => void
  /** The pane's width in cells. */
  columns: number
  /** The pane's height in rows, so the footer can sit on its bottom edge. */
  rows?: number
  /** The session's share of the machine, for the footer. */
  resources: Resources | null
  /** The branches the session started, newest first. */
  branches: BranchView[]
  /** The branch a PR is being created for, if any. */
  creating: string | null
  /** Hide a branch. */
  hideBranch: (branch: string) => void
  /** Create PR on a branch without one. */
  createPr: (branch: string) => void
  /** Merge on an open PR. */
  mergePr: (pr: GitPr) => void
  /** What the mod cost, for the debug footer. */
  perf: PerfSnapshot
  /** The clock elapsed times and resets are drawn against. */
  at: number
  /** The workspaces' last `gh pr list`: whether it failed, and when it last read good (the terminal shows it). */
  workspacesGh?: WorkspacesGh | null
  /** Whether the pane has the keyboard (`e.props.isFocused`); the terminal's kit takes it. */
  focused?: boolean
}

/** What the app mode borrows from register.tsx, passed in so this file has no cycle back. */
export type Helpers = {
  colorOf: (segments: Snapshot['segments'], i: number) => string | undefined
  limitLabel: (kind: string) => string
  resetIn: (resetsAt: string | undefined, at: number) => string
  buildTree: (list: Agent[]) => Array<{ agent: Agent; depth: number }>
}

/**
 * A context category's short name and colour: the fixed overhead in shades of
 * slate (it only says how much), messages in blue (the part that grows).
 */
// Grouped into four, so the legend is short: what the system brings, what MCP
// brings, what the person's setup brings (memory, skills, agents), and the conversation.
export const CATEGORY: Record<string, { name: string; color: string }> = {
  'System prompt': { name: 'System', color: RAMP.slate[0] },
  'System tools': { name: 'System', color: RAMP.slate[0] },
  'MCP tools': { name: 'MCP', color: RAMP.slate[1] },
  'MCP server instructions': { name: 'MCP', color: RAMP.slate[1] },
  'Custom agents': { name: 'Memory', color: RAMP.slate[2] },
  'Memory files': { name: 'Memory', color: RAMP.slate[2] },
  Skills: { name: 'Memory', color: RAMP.slate[2] },
  Messages: { name: 'Messages', color: C.blue },
}

/** Three letters for a context category: what the terminal layout's chips show. */
export const tagOf = (name: string): string => {
  const known: Record<string, string> = {
    'System prompt': 'sys',
    'System tools': 'tls',
    'MCP tools': 'mcp',
    'Custom agents': 'agt',
    'Memory files': 'mem',
    Skills: 'skl',
    Messages: 'msg',
  }
  return known[name] ?? name.slice(0, 3).toLowerCase()
}

/** An agent's status as its icon's colour: running or queued blue, done green, failed red, else grey. */
export const statusColor = (status: string): string =>
  status === 'running' || status === 'pending' ? C.blue : status === 'completed' ? C.ok : status === 'failed' ? C.bad : MUTED

/** A mark for each kind of thing: its icon on the app surfaces, its one-cell glyph on the terminal. */
type Mark = { icon: string; glyph: string }

/**
 * Each kind of agent's mark: code for a lane lead, tools for a worker, a bolt for
 * a quick fix, a checklist (◎ on the terminal, as ✓ means done) for a reviewer,
 * a telescope to explore, a task list to plan, a robot for the general agent and
 * a book for the guide; the agents sparkle for any other.
 */
const AGENT_MARK: Record<string, Mark> = {
  developer: { icon: 'code', glyph: '◆' },
  worker: { icon: 'tools', glyph: '◇' },
  'quick-fix': { icon: 'zap', glyph: '↯' },
  reviewer: { icon: 'checklist', glyph: '◎' },
  explore: { icon: 'telescope', glyph: '⌕' },
  plan: { icon: 'tasklist', glyph: '≡' },
  'general-purpose': { icon: 'hubot', glyph: '○' },
  'claude-code-guide': { icon: 'book', glyph: '?' },
}
export const agentMark = (type: string): Mark => AGENT_MARK[type.toLowerCase()] ?? { icon: GLYPH.agents, glyph: '✦' }

/** Each kind of tool call's mark, for an agent's "doing now" line. */
const DOING_MARK: Record<string, Mark> = {
  bash: { icon: 'terminal', glyph: '$' },
  edit: { icon: 'pencil', glyph: '✎' },
  read: { icon: 'eye', glyph: '◇' },
  search: { icon: 'search', glyph: '⌕' },
  web: { icon: 'globe', glyph: '◎' },
  agent: { icon: GLYPH.agents, glyph: '✦' },
  mcp: { icon: 'plug', glyph: '⏚' },
  other: { icon: 'dot-fill', glyph: '·' },
}
export const doingMark = (d: Doing): Mark => DOING_MARK[d.kind] ?? DOING_MARK.other!

/**
 * A "doing now" line's argument in what's left of `cells` after its name and a
 * space, cut in the middle (`mods/…/register.tsx`) so its end stays in view.
 */
export const doingArg = (d: Doing, cells: number): string | undefined =>
  d.arg ? middle(d.arg, Math.max(8, cells - [...d.text].length - 1)) : undefined

/**
 * A PR's state as one colour: merged purple; closed or draft grey; an open one green,
 * red while it has conflicts (on GitHub or in the checkout), amber while CI fails.
 */
export const prColor = (pr: GitPr, conflicted: boolean) =>
  pr.state === 'MERGED'
    ? C.purple
    : pr.state === 'CLOSED' || pr.isDraft
      ? MUTED
      : conflicted || pr.conflicting
        ? C.bad
        : pr.checks.failed
          ? C.warn
          : C.ok

/** "2h18", "3d4h", from "resets in 2h 18m". */
export const compact = (s: string) => s.replace('resets in ', '').replace(/ /g, '')

/** The context bar's free room: a step brighter than the empty track. */
const FREE = 'rgba(128,128,128,0.34)'
/** The context bar's buffer past compaction: the compaction mark's amber, faint. */
const BUFFER = 'rgba(227,163,59,0.32)'

export const shortTool = (name: string) => (name.startsWith('mcp__') ? (name.split('__').pop() ?? name) : name)

/**
 * The footer's lead: the session's share of the machine, ours against the
 * system's, under muted three-letter labels; ours turns amber or red when it's a big share.
 */
export const machine = (k: ReturnType<typeof kit>, r: Resources | null): RenderElement[] => {
  if (!r) return []
  const hot = (part: number, whole: number) => (whole > 0 && part / whole > 0.5 ? C.bad : whole > 0 && part / whole > 0.25 ? C.warn : undefined)
  const pctOf = (n: number) => `${Math.round(n)}%`
  return [
    k.share('cpu', 'cpu', pctOf(r.cpu), pctOf(r.cpuAll), hot(r.cpu, r.cpuAll)),
    k.share('mem', 'mem', bytes(r.mem), bytes(r.memAll), hot(r.mem, r.memAll)),
    k.share('net', 'net', r.net === null ? '–' : bytes(r.net), bytes(r.netAll), r.net === null ? undefined : hot(r.net, r.netAll)),
  ]
}

/** The context window's used segments summed into their groups, in the groups' order; the free room up to compaction; the buffer past it. */
export const contextParts = (snap: Snapshot | null) => {
  const parts: { value: number; color: string; label: string }[] = []
  for (const s of snap?.segments ?? []) {
    if (s.kind !== 'used' || s.tokens <= 0) continue
    const c = CATEGORY[s.name] ?? { name: s.name, color: INK }
    const at = parts.find(p => p.label === c.name)
    if (at) at.value += s.tokens
    else parts.push({ value: s.tokens, color: c.color, label: c.name })
  }
  const free = snap ? Math.max(0, (snap.compactAt ?? snap.max) - snap.total) : 0
  const buffer = snap?.compactAt && snap.max > snap.compactAt ? snap.max - snap.compactAt : 0
  return { parts, free, buffer }
}

/**
 * The activity chart's data: tool calls per turn, each turn's column sliced by tool.
 * The busiest tools take shades of blue (one series, parts told apart), the rest one slate slice.
 */
export const activityChart = (a: Activity) => {
  const allTools = Object.entries(a.tools).sort((x, y) => y[1].n - x[1].n)
  const named = allTools.slice(0, RAMP.blue.length).map(([name], i) => ({ name, color: RAMP.blue[i]! }))
  const OTHER = RAMP.slate[1]
  const SLOTS = 16
  const log = a.turnLog.slice(-SLOTS)
  const first = a.turns - log.length + 1
  const sliced = log.map(p => {
    const by = p.tools ?? {}
    const other = Object.entries(by).reduce((n, [name, c]) => n + (named.some(t => t.name === name) ? 0 : c), 0)
    // Stacked bottom up, the busiest tool at the base; a turn without calls keeps a sliver.
    const stack = [...named.map(t => ({ value: by[t.name] ?? 0, color: t.color })), { value: other, color: OTHER }].reverse()
    return stack.some(x => x.value > 0) ? stack : [{ value: 0.05, color: TRACK }]
  })
  const peak = Math.max(0, ...log.map(p => p.calls ?? 0))
  const otherCount = allTools.slice(named.length).reduce((n, [, t]) => n + t.n, 0)
  const cacheIn = a.turnLog.reduce((n, p) => n + p.cacheRead, 0)
  const allIn = a.turnLog.reduce((n, p) => n + p.cacheRead + p.cacheWrite + p.input, 0)
  // Turn numbers under the first, middle and last bar.
  const ticks = log.length ? [0, Math.floor((log.length - 1) / 2), log.length - 1].filter((v, i, xs) => xs.indexOf(v) === i) : []
  return { named, OTHER, SLOTS, log, first, sliced, peak, otherCount, cacheIn, allIn, ticks }
}

export const renderDesktop = (els: AppElements, d: DesktopData, fx: Helpers): RenderElement => {
  const { Box, Text } = els
  const k = kit(els, 'desktop', d.columns, { flow: { on: d.columnsOn, toggle: d.toggleColumns } })
  // A section's width: the pane's, or a flow column's when the pane is wide (at most six sections share it).
  const lane = k.flowColumns(6).width
  const a = d.activity
  const snap = d.snap
  const fold = (id: string) => ({ collapsed: d.collapsed.includes(id), onToggle: () => d.toggle(id) })

  const toolCalls = Object.values(a.tools).reduce((n, t) => n + t.n, 0)
  const running = d.agents.filter(x => x.status === 'running' || x.status === 'pending').length

  // ---- context: the instrument's main meter ----
  const { parts, free, buffer } = contextParts(snap)
  // What's left, as two more shades of the same bar: the free room up to compaction,
  // then the buffer past it (amber, as the compaction mark is), with their own legend entries.
  const room = [...parts]
  if (snap) {
    if (free > 0) room.push({ value: free, color: FREE, label: 'Free' })
    if (buffer > 0) room.push({ value: buffer, color: BUFFER, label: 'Buffer' })
  }
  const context = k.section({
    id: 'context',
    icon: GLYPH.context,
    title: 'Context',
    right: snap ? (
      <Text>
        <Text bold color={levelColor(snap.percent)}>{`${snap.percent}%`}</Text>
        <Text color={GRAY.mid}>{` of ${tokens(snap.max)}`}</Text>
      </Text>
    ) : (
      <Text color={GRAY.mid}>measuring…</Text>
    ),
    ...fold('context'),
    children: snap
      ? [
          <Box key="meter" flexDirection="column">
            {k.bar(room, snap.max, { height: 0.5 })}
            {/* No compaction mark: the buffer's shade starts where it falls. */}
            {k.scale()}
            {k.axis(
              'ctx-axis',
              [0, 0.25, 0.5, 0.75, 1].map(f => ({ at: f, text: f === 0 ? '0' : tokens(snap.max * f) })),
            )}
          </Box>,
          <Box key="legend" marginTop={SPACE.block} width="100%">
            {k.legend(
              'ctx',
              room.map(p => ({ label: p.label, color: p.color, figure: tokens(p.value) })),
              2,
            )}
          </Box>,
        ]
      : null,
  })

  // ---- limits ----
  const windows = d.limits ?? []
  const limits = windows.length
    ? k.section({
        id: 'limits',
        icon: GLYPH.limits,
        title: 'Limits',
        ...fold('limits'),
        children: windows.map(w =>
          k.reading(`limit-${w.kind}`, {
            label: fx.limitLabel(w.kind),
            value: Math.min(100, Math.max(0, w.percent)),
            max: 100,
            color: levelColor(w.percent),
            figure: `${Math.round(w.percent)}%`,
            unit: w.resetsAt ? compact(fx.resetIn(w.resetsAt, d.at)) : undefined,
          }),
        ),
      })
    : null

  // ---- activity: tool calls per turn, each bar sliced by tool ----
  const { named, OTHER, SLOTS, log, first, sliced, peak, otherCount, cacheIn, allIn, ticks } = activityChart(a)
  const activity =
    log.length || toolCalls
      ? k.section({
          id: 'activity',
          icon: GLYPH.tools,
          title: 'Activity',
          right: k.summary([[String(peak), 'peak'], [`${allIn ? Math.round((cacheIn / allIn) * 100) : 0}%`, 'cached']]),
          ...fold('activity'),
          children: [
            <Box key="chart" flexDirection="column">
              {k.columns(sliced, { slots: SLOTS, height: 3.5 })}
              {k.axis(
                'act-axis',
                ticks.map(i => ({ at: (i + 0.5) / SLOTS, text: String(first + i).padStart(2, '0') })),
              )}
            </Box>,
            <Box key="legend" marginTop={SPACE.block} width="100%">
              {k.legend('act', [
                ...named.map(t => ({ label: shortTool(t.name), color: t.color, figure: String(a.tools[t.name]!.n) })),
                ...(otherCount ? [{ label: 'Other', color: OTHER, figure: String(otherCount) }] : []),
              ])}
            </Box>,
          ],
        })
      : null

  // ---- agents ----
  const agents = d.agents.length
    ? k.section({
        id: 'agents',
        icon: GLYPH.agents,
        title: 'Agents',
        right: k.summary([[String(d.agents.length), 'started'], running ? [String(running), 'running', C.blue] : null]),
        ...fold('agents'),
        // A tile per agent, one line, and a second while it runs:
        //   [type icon, status colour] description     12k  3m
        //   [tool icon] Editing kit/ui.tsx
        // The type and status are the icon's tooltip.
        children: fx.buildTree(d.agents).map(({ agent, depth }, i) => {
          const x = d.extras[agent.id]
          const ms = agent.status === 'running' && x?.startedAt !== undefined ? d.at - x.startedAt : x?.durationMs
          const color = statusColor(agent.status)
          const who = `${agent.type} · ${agent.status.toLowerCase()}`
          const doing = agent.status === 'running' ? x?.doing : undefined
          const row = (key: string, l: (RenderElement | null)[], r: (RenderElement | null)[]) => (
            <Box key={key} flexDirection="row" justifyContent="space-between" gap={SPACE.item} width="100%">
              <Box flexDirection="row" alignItems="center" gap={SPACE.pair} flexShrink={1} minWidth={0} overflow="hidden">
                {l}
              </Box>
              <Box flexDirection="row" alignItems="center" gap={SPACE.item} flexShrink={0}>
                {r}
              </Box>
            </Box>
          )
          return (
            // Indented by padding, inside the full width, so a nested tile ends at the same right edge.
            <Box key={`agent-${agent.id}`} width="100%" paddingLeft={depth * 2} marginTop={i === 0 ? 0 : SPACE.block}>
              {k.tile(`tile-${agent.id}`, [
                row(
                  'l1',
                  [
                    <Box key="i" flexShrink={0}>
                      {k.icon(agentMark(agent.type).icon, color, undefined, { tooltip: who })}
                    </Box>,
                    <Text key="d" wrap="truncate">{agent.description || agent.type}</Text>,
                  ],
                  [
                    x?.tokens !== undefined ? <Text key="t" color={GRAY.mid}>{tokens(x.tokens)}</Text> : null,
                    ms !== undefined ? <Text key="ms" color={GRAY.dark}>{short(ms)}</Text> : null,
                  ],
                ),
                // What it's doing now, while it runs: the tool's icon, its name, then its argument dim.
                doing
                  ? row(
                      'l2',
                      [
                        <Box key="i" flexShrink={0}>
                          {k.icon(doingMark(doing).icon, MUTED)}
                        </Box>,
                        <Text key="t" wrap="truncate">
                          {doing.text}
                          {doing.arg ? <Text color={GRAY.mid}>{` ${doingArg(doing, lane - depth * 2 - 6)}`}</Text> : null}
                        </Text>,
                      ],
                      [],
                    )
                  : null,
              ])}
            </Box>
          )
        }),
      })
    : null

  // ---- accounting: what the session cost, and on what ----
  const accounting = k.section({
    id: 'accounting',
    icon: GLYPH.cost,
    title: 'Accounting',
    right: k.summary([[a.cost !== undefined ? money(a.cost) : '–']]),
    ...fold('accounting'),
    children: [snap ? k.prop('model', 'Model', snap.model) : k.prop('model', 'Model', '–')],
  })

  return k.pinned(
    // In columns when the pane is wide; one stack at a sidebar's width.
    k.flow('sections', [context, limits, activity, agents, ...renderBranches(els, k, d, fold), accounting]),
    k.perf(d.perf, { lead: machine(k, d.resources) }),
    d.rows,
  )
}

/**
 * Workspaces: the branches the session started, as the desktop app tracks them,
 * each in its own tile: the PR's state as an icon and a word, the PR's title on a
 * line of its own, then its number, where it lives, changes, CI and the actions.
 */
const renderBranches = (els: AppElements, k: ReturnType<typeof kit>, d: DesktopData, fold: (id: string) => { collapsed: boolean; onToggle: () => void }): RenderElement[] => {
  const { Box, Text, Link, Button } = els
  const entries = d.branches.map((b, i) => {
    const pr = b.pr
    const open = pr?.state === 'OPEN'
    const color = pr ? prColor(pr, b.conflicted > 0) : MUTED
    const ci: [string, string] | null = b.conflicted
      ? [`${b.conflicted} conflict${b.conflicted === 1 ? '' : 's'}`, C.bad]
      : !pr || !open
        ? null
        : pr.conflicting
          ? ['conflicts', C.bad]
          : pr.checks.failed
          ? [`${pr.checks.failed} failing`, C.warn]
          : pr.checks.pending
            ? [`${pr.checks.pending} pending`, C.blue]
            : pr.checks.passed
              ? ['passing', C.ok]
              : null
    const action =
      !Button || !b.exists
        ? null
        : d.creating === b.branch
          ? <Text color={GRAY.mid}>creating PR…</Text>
          : !pr
            ? <Button key={`create-${b.branch}`} plain label="Create PR" onPress={() => d.createPr(b.branch)} />
            : open && !pr.isDraft
              ? <Button key={`merge-${pr.number}`} plain label="Merge" onPress={() => d.mergePr(pr)} />
              : null
    // A tile per branch, three lines:
    //   [pr icon] branch                    hide
    //   A neater inspector, the PR's title, the full width
    //   #9  awesome-claude      +412 −96  1 failing  Merge
    // The PR's state is the icon's glyph and colour, no word; a deleted branch's name is struck through.
    const iconKey = !pr ? GLYPH.branch : pr.state === 'MERGED' ? 'pr-merged' : pr.state === 'CLOSED' ? 'pr-closed' : pr.isDraft ? 'pr-draft' : 'pr-open'
    const where = b.worktree ? `${b.place} (worktree)` : b.place
    const row = (key: string, l: RenderElement | (RenderElement | null)[], r: (RenderElement | null)[]) => (
      <Box key={key} flexDirection="row" justifyContent="space-between" gap={SPACE.item} width="100%">
        <Box flexDirection="row" alignItems="center" gap={SPACE.pair} flexShrink={1} minWidth={0} overflow="hidden">
          {l}
        </Box>
        <Box flexDirection="row" alignItems="center" gap={SPACE.item} flexShrink={0}>
          {r}
        </Box>
      </Box>
    )
    return (
      <Box key={`branch-${b.branch}`} width="100%" marginTop={i === 0 ? 0 : SPACE.block}>
        {k.tile(`tile-${b.branch}`, [
          row(
            'l1',
            [
              k.icon(iconKey, color),
              <Text key="b" wrap="truncate" strikethrough={!b.exists} dimColor={!b.exists}>
                {b.branch}
              </Text>,
            ],
            [
              Button ? (
                // dimColor, not a grey child Text: the desktop draws a Button's label alone.
                <Button key={`hide-${b.branch}`} plain dimColor label="hide" onPress={() => d.hideBranch(b.branch)} />
              ) : null,
            ],
          ),
          pr ? (
            <Text key="title" wrap="truncate">
              {pr.title}
            </Text>
          ) : null,
          row(
            'l3',
            [
              // The PR's number reads as a link by its blue alone, no underline.
              pr ? (
                <Link key="n" href={pr.url} label={`#${pr.number}`}>
                  <Text color={C.blue}>{`#${pr.number}`}</Text>
                </Link>
              ) : null,
              <Text key="p" color={GRAY.mid} wrap="truncate">
                {where}
              </Text>,
            ],
            [
              b.insertions || b.deletions ? (
                // Lines added green, removed red, as a diff colours them.
                <Text key="d">
                  <Text color={C.ok}>{`+${b.insertions}`}</Text>
                  <Text color={C.bad}>{` −${b.deletions}`}</Text>
                </Text>
              ) : null,
              ci ? <Text key="ci" color={ci[1]}>{ci[0]}</Text> : null,
              action,
            ],
          ),
        ])}
      </Box>
    )
  })
  if (!entries.length) return []
  const merged = d.branches.filter(b => b.pr?.state === 'MERGED').length
  const openPrs = d.branches.filter(b => b.pr?.state === 'OPEN').length
  return [
    k.section({
      id: 'workspaces',
      icon: GLYPH.branch,
      title: 'Workspaces',
      right: k.summary([openPrs ? [String(openPrs), 'open', C.blue] : null, merged ? [String(merged), 'merged', C.purple] : null]),
      ...fold('workspaces'),
      children: entries,
    }),
  ]
}

files.hooks/terminal.tsx:
import type { Elements, RenderElement } from 'claude-code'

import { ago, basename, money, short, tokens } from '../kit/format'
import { C, GLYPH, MUTED, TRACK, TREE, levelColor } from '../kit/tokens'
import type { StatusKind } from '../kit/tokens'
import { MEASURE, kit } from '../kit/ui'
import type { Kit } from '../kit/ui'

import type { Agent, BranchView, GitFile, GitInfo, GitPr, TreeRow } from '../types'
import { activityChart, agentMark, compact, contextParts, doingArg, doingMark, machine, prColor, shortTool, statusColor } from './desktop'
import type { DesktopData } from './desktop'

/*
 * The terminal mode: the same instrument inspector as the desktop, in cells.
 * Same sections in the same order (Context, Limits, Activity, Agents,
 * Workspaces, Accounting), plus the session's own checkout and its pull
 * requests (Git), which the terminal has always shown. Every row is drawn
 * with the kit's terminal primitives, sized from the pane's `bodyColumns`.
 */

/** The elements the terminal draws with. */
export type TermElements = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'>

/** What the terminal mode borrows from register.tsx, passed in so this file has no cycle back. */
export type TermHelpers = {
  limitLabel: (kind: string) => string
  resetIn: (resetsAt: string | undefined, at: number) => string
  fitTree: (list: Agent[], budget: number) => { rows: TreeRow[]; hidden: number }
  subSummary: (row: TreeRow) => string
}

/** The most agent rows drawn; finished subtrees fold first, then the rest is counted. */
const AGENT_ROWS = 12
/** The most pull requests the Git section lists. */
const GIT_PRS = 3


/** A PR's icon key: its state, as GitHub draws it. */
const prIcon = (pr: GitPr) => (pr.state === 'MERGED' ? 'pr-merged' : pr.state === 'CLOSED' ? 'pr-closed' : pr.isDraft ? 'pr-draft' : 'pr-open')

/** A PR's checks as one status and word, or null when there's nothing to say. */
const prChecks = (pr: GitPr, conflicted = 0): [StatusKind, string] | null => {
  if (pr.state === 'MERGED') return ['merged', 'merged']
  if (pr.state === 'CLOSED') return ['stopped', 'closed']
  if (conflicted) return ['failed', `${conflicted} conflict${conflicted === 1 ? '' : 's'}`]
  if (pr.conflicting) return ['failed', 'conflicts']
  if (pr.checks.failed) return ['failed', `${pr.checks.failed} failing`]
  if (pr.checks.pending) return ['pending', `${pr.checks.pending} pending`]
  if (pr.checks.passed) return ['done', 'passing']
  return null
}

/** A changed file's colour: conflicts and deletions red, additions and staged green, edits amber, untracked grey. */
const fileColor = (f: GitFile) =>
  f.kind === 'conflict' || f.kind === 'deleted' ? C.bad : f.kind === 'added' || f.staged ? C.ok : f.kind === 'untracked' ? MUTED : C.warn

/** The folder a path sits in, or '' at the top. */
const dirOf = (path: string) => path.split(/[\\/]/).slice(0, -1).join('/')

/** How old last-good figures are, for a header's stale state: 40s, 5m, 3h; nothing when unknown. */
const since = (at: number | undefined, now: number) => {
  if (!at) return undefined
  const ms = Math.max(0, now - at)
  return ms < 60_000 ? `${Math.floor(ms / 1_000)}s` : ago(ms)
}

/** Tokens a turn added: its input, output and cache writes (cache reads restate the context, which Context shows). */
const turnTokens = (p: { input: number; output: number; cacheWrite: number }) => p.input + p.output + p.cacheWrite

export const renderTerminal = (els: TermElements, d: DesktopData, fx: TermHelpers): RenderElement => {
  const { Box, Text } = els
  // A dashboard of readings: drawn to the kit's measure, so a wide pane doesn't spread them apart.
  const k = kit(els, 'terminal', d.columns, { focused: d.focused, measure: MEASURE })
  const a = d.activity
  const snap = d.snap
  const fold = (id: string) => ({ collapsed: d.collapsed.includes(id), onToggle: () => d.toggle(id) })
  const running = d.agents.filter(x => x.status === 'running' || x.status === 'pending').length

  // ---- context: one row: the used groups as the heavy line, then the free room and the
  // buffer past the compaction point as the light rail (dim, then amber); the legend under it ----
  const { parts, free, buffer } = contextParts(snap)
  const room = [
    ...(free > 0 ? [{ value: free, color: TRACK, label: 'Free', room: true }] : []),
    ...(buffer > 0 ? [{ value: buffer, color: C.warn, label: 'Buffer', room: true }] : []),
  ]
  const context = k.section({
    id: 'context',
    icon: GLYPH.context,
    title: 'Context',
    right: snap ? k.summary([[`${snap.percent}%`, `of ${tokens(snap.max)}`, levelColor(snap.percent)]]) : undefined,
    loading: !snap,
    ...fold('context'),
    children: snap
      ? [
          <Box key="meter">{k.bar([...parts, ...room], snap.max)}</Box>,
          // Keyed with the bar's own glyphs: ━ for what's used, ─ for the room.
          k.legend(
            'ctx',
            [...parts, ...room].map(p => ({ label: p.label, color: p.color, figure: tokens(p.value), room: 'room' in p })),
            undefined,
            { bar: true },
          ),
        ]
      : [k.note('ctx-reading', 'Reading context…', 'loading')],
  })

  // ---- limits ----
  const windows = d.limits ?? []
  // The header names the fullest window, so a folded section (or the narrow floor, which draws headers only) still says it.
  const fullest = windows.reduce<(typeof windows)[number] | null>((m, w) => (!m || w.percent > m.percent ? w : m), null)
  const limits = windows.length
    ? k.section({
        id: 'limits',
        icon: GLYPH.limits,
        title: 'Limits',
        right: fullest ? k.summary([[`${Math.round(fullest.percent)}%`, fx.limitLabel(fullest.kind).toLowerCase(), levelColor(fullest.percent)]]) : undefined,
        // The readings say it while the section is open.
        restated: true,
        ...fold('limits'),
        children: windows.map(w =>
          k.reading(`limit-${w.kind}`, {
            label: fx.limitLabel(w.kind),
            value: Math.min(100, Math.max(0, w.percent)),
            max: 100,
            color: levelColor(w.percent),
            figure: `${Math.round(w.percent)}%`,
            unit: w.resetsAt ? compact(fx.resetIn(w.resetsAt, d.at)) : undefined,
          }),
        ),
      })
    : null

  // ---- activity: tool calls per turn ----
  const chart = activityChart(a)
  const toolCalls = Object.values(a.tools).reduce((n, t) => n + t.n, 0)
  // The chart's own width (whole cells per slot), so the turn numbers sit under their columns.
  const chartWidth = Math.max(1, Math.floor(k.width / chart.SLOTS)) * chart.SLOTS
  const activity =
    chart.log.length || toolCalls
      ? k.section({
          id: 'activity',
          icon: GLYPH.tools,
          title: 'Activity',
          right: k.summary([
            [String(chart.peak), 'peak'],
            // Narrow, the cache share goes first: the header would be cut.
            k.width >= 50 ? [`${chart.allIn ? Math.round((chart.cacheIn / chart.allIn) * 100) : 0}%`, 'cached'] : null,
          ]),
          ...fold('activity'),
          children: [
            <Box key="chart" flexDirection="column">
              {k.columns(chart.sliced, { slots: chart.SLOTS, height: 3 })}
              {k.axis(
                'act-axis',
                chart.ticks.map(i => ({ at: (i + 0.5) / chart.SLOTS, text: String(chart.first + i).padStart(2, '0') })),
                chartWidth,
              )}
            </Box>,
            // A chart taller than a row is its own block: its legend after one blank row.
            <Box key="legend" marginTop={k.space.block}>
              {k.legend('act', [
                ...chart.named.map(t => ({ label: shortTool(t.name), color: t.color, figure: String(a.tools[t.name]!.n) })),
                ...(chart.otherCount ? [{ label: 'Other', color: chart.OTHER, figure: String(chart.otherCount) }] : []),
              ])}
            </Box>,
          ],
        })
      : null

  // ---- agents: a tree, each row its status, description, type, tokens and time ----
  const { rows: tree, hidden } = fx.fitTree(d.agents, AGENT_ROWS)
  const agents = d.agents.length
    ? k.section({
        id: 'agents',
        icon: GLYPH.agents,
        title: 'Agents',
        right: k.summary([[String(d.agents.length), 'started'], running ? [String(running), 'running', C.blue] : null]),
        ...fold('agents'),
        children: [
          ...tree.flatMap(row => {
            const { agent } = row
            const x = d.extras[agent.id]
            const ms = agent.status === 'running' && x?.startedAt !== undefined ? d.at - x.startedAt : x?.durationMs
            const sub = fx.subSummary(row)
            // While it runs, a line under it with its latest tool call, under its text: the tool's
            // glyph dim, its name, its argument dim. The tree's guides carry on through it, and a
            // pipe under the mark when its children follow.
            const doing =
              agent.status === 'running' && x?.doing
                ? (() => {
                    const d0 = x.doing
                    const guides = row.depth ? row.guides.map(g => (g ? TREE.pipe : TREE.blank)).join('') + (row.last ? TREE.blank : TREE.pipe) : ''
                    const prefix = guides + (row.descendants > 0 && !row.folded ? TREE.pipe : TREE.blank)
                    // The row less its tree, the glyph's two cells and the note's two-cell gap.
                    const note = doingArg(d0, k.width - [...prefix].length - 4)
                    return k.item(`doing-${agent.id}`, { tree: prefix, lead: doingMark(d0).glyph, text: d0.text, note })
                  })()
                : null
            // Its kind of agent as a glyph, coloured by its status.
            const line = k.item(`agent-${agent.id}`, {
              tree: row.depth ? k.tree(row.guides, row.last, row.depth) : undefined,
              lead: agentMark(agent.type).glyph,
              leadColor: statusColor(agent.status),
              text: agent.description || agent.type,
              note: [agent.description ? agent.type : '', sub].filter(Boolean).join(' · '),
              // Narrow, the tokens go before the time.
              right: [
                x?.tokens !== undefined ? { part: tokens(x.tokens), drop: 2 } : null,
                ms !== undefined ? { part: short(ms), drop: 1 } : null,
              ],
            })
            return doing ? [line, doing] : [line]
          }),
          hidden > 0 ? k.note('agents-more', `… ${hidden} more`) : null,
        ],
      })
    : null

  // ---- accounting: the cost, the model, and the tokens each turn added as a sparkline ----
  // A spark rather than columns: one series over time with no parts to stack, and Braille's two
  // points a cell fit the whole turn log (40) in 20 cells, where columns show one turn a cell.
  const perTurn = a.turnLog.map(turnTokens)
  const SPARK_MIN = 4
  const accounting = k.section({
    id: 'accounting',
    icon: GLYPH.cost,
    title: 'Accounting',
    right: k.summary([[a.cost !== undefined ? money(a.cost) : '–']]),
    ...fold('accounting'),
    children: [
      k.prop('model', 'Model', snap ? snap.model : '–'),
      // The last turn's figure, then the spark on the same row, scaled to the log's peak; with
      // fewer than SPARK_MIN turns there's no shape to read, so the figure stands alone.
      perTurn.length
        ? k.prop(
            'turn-tokens',
            'Tokens',
            perTurn.length < SPARK_MIN ? (
              `${tokens(perTurn.at(-1)!)} last turn`
            ) : (
              <Box flexDirection="row" gap={k.space.group}>
                <Text wrap="truncate">{`${tokens(perTurn.at(-1)!)} last turn`}</Text>
                {k.spark(perTurn, { height: 1, width: Math.min(20, Math.ceil(perTurn.length / 2)) })}
              </Box>
            ),
          )
        : null,
    ],
  })

  return k.pinned(
    [context, limits, activity, agents, ...workspaces(els, k, d, fold), gitSection(els, k, d, fold), accounting],
    k.perf(d.perf, { lead: machine(k, d.resources) }),
    d.rows,
  )
}

type Fold = (id: string) => { collapsed: boolean; onToggle: () => void }

/**
 * Workspaces: the branches the session started, two rows each: the PR's state as
 * its icon, the branch and its actions; then the PR's number and title, the
 * lines changed and CI.
 */
const workspaces = (els: TermElements, k: Kit, d: DesktopData, fold: Fold): RenderElement[] => {
  const { Box, Text } = els
  if (!d.branches.length) return []
  const entries = d.branches.map((b: BranchView, i) => {
    const pr = b.pr
    const open = pr?.state === 'OPEN'
    // A merged or closed PR's state is its icon (and the header's count): no word for it again.
    const ci = pr ? (open ? prChecks(pr, b.conflicted) : null) : b.conflicted ? (['failed', `${b.conflicted} conflicts`] as [StatusKind, string]) : null
    const main =
      !b.exists
        ? null
        : d.creating === b.branch
          ? null
          : !pr
            ? { key: `create-${b.branch}`, label: 'Create PR', onPress: () => d.createPr(b.branch) }
            : open && !pr.isDraft
              ? { key: `merge-${pr.number}`, label: 'Merge', onPress: () => d.mergePr(pr) }
              : null
    const where = b.worktree ? `${b.place} (worktree)` : b.place
    return (
      <Box key={`branch-${b.branch}`} flexDirection="column" marginTop={i === 0 ? 0 : k.space.block}>
        {k.item(`branch-${b.branch}-head`, {
          lead: pr ? prIcon(pr) : GLYPH.branch,
          leadColor: pr ? prColor(pr, b.conflicted > 0) : MUTED,
          text: b.branch,
          note: pr ? `#${pr.number}` : undefined,
          dim: !b.exists,
          // The actions sit beside the branch they act on, not alone on the far edge.
          after: k.actions(`branch-${b.branch}-actions`, [main, { key: `hide-${b.branch}`, label: 'hide', quiet: true, onPress: () => d.hideBranch(b.branch) }]),
          right: [d.creating === b.branch ? { part: 'creating PR…', drop: 1 } : null],
        })}
        {k.item(`branch-${b.branch}-pr`, {
          indent: k.edge.left,
          text: pr ? pr.title : where,
          dim: !pr,
          // Narrow, the lines changed go before CI.
          right: [
            b.insertions || b.deletions
              ? {
                  part: (
                    <Text key="diff">
                      <Text {...k.ink(C.ok)}>{`+${b.insertions}`}</Text>
                      <Text {...k.ink(C.bad)}>{` −${b.deletions}`}</Text>
                    </Text>
                  ),
                  drop: 1,
                }
              : null,
            ci ? k.status(ci[0], ci[1], 'ci') : null,
          ],
        })}
      </Box>
    )
  })
  const merged = d.branches.filter(b => b.pr?.state === 'MERGED').length
  const openPrs = d.branches.filter(b => b.pr?.state === 'OPEN').length
  return [
    k.section({
      id: 'workspaces',
      icon: GLYPH.branch,
      title: 'Workspaces',
      // A failed gh read keeps the last PRs: the header says so, and how old they are.
      right: k.summary([openPrs ? [String(openPrs), 'open', C.blue] : null, merged ? [String(merged), 'merged', C.purple] : null], {
        failed: Boolean(d.workspacesGh?.failed),
        age: d.workspacesGh?.failed ? since(d.workspacesGh.at, d.at) : undefined,
      }),
      ...fold('workspaces'),
      children: entries,
    }),
  ]
}

/**
 * Git: the session's own checkout (branch, upstream, worktree, what changed) and
 * the open pull requests it has, each a list row with its status.
 */
const gitSection = (els: TermElements, k: Kit, d: DesktopData, fold: Fold): RenderElement => {
  const { Box, Text } = els
  const repo = d.git
  const hub = d.gh
  const head = (right: RenderElement | null, children: (RenderElement | null)[], loading = false) =>
    k.section({ id: 'git', icon: GLYPH.branch, title: 'Git', right: right ?? undefined, loading, ...fold('git'), children })
  if (repo === null) return head(null, [k.note('git-reading', 'Reading git…', 'loading')], true)
  if (!repo.ok) return head(null, [k.note('git-note', repo.note)])
  const g: GitInfo = repo
  // A failed git or gh read keeps the last-good figures: the header says so, with the older one's age.
  const ghHere = hub && hub.root === g.root ? hub : null
  const failed = Boolean(g.failed || ghHere?.failed)
  const failedAt = [g.failed ? g.at : undefined, ghHere?.failed ? ghHere.at : undefined].filter((x): x is number => Boolean(x))
  const state = failed ? { failed, age: failedAt.length ? since(Math.min(...failedAt), d.at) : undefined } : {}

  // The branch row: where the checkout is against its upstream.
  const sync: (RenderElement | string | null)[] = g.detached
    ? [k.status('warn', 'detached', 'sync')]
    : !g.upstream
      ? ['no upstream']
      : g.ahead || g.behind
        ? [
            g.ahead ? <Text key="ahead">{`${GLYPH.up}${g.ahead}`}</Text> : null,
            g.behind ? <Text key="behind" {...k.ink(C.warn)}>{`${GLYPH.down}${g.behind}`}</Text> : null,
          ]
        : [k.status('done', 'synced', 'sync')]

  const changes =
    g.conflicted || g.staged || g.modified || g.untracked || g.insertions || g.deletions
      ? k.summary([
          g.conflicted ? [String(g.conflicted), 'conflicted', C.bad] : null,
          g.staged ? [String(g.staged), 'staged', C.ok] : null,
          g.modified ? [String(g.modified), 'modified', C.warn] : null,
          g.untracked ? [String(g.untracked), 'untracked'] : null,
          g.insertions ? [`+${g.insertions}`, undefined, C.ok] : null,
          g.deletions ? [`−${g.deletions}`, undefined, C.bad] : null,
        ])
      : k.status('done', 'working tree clean', 'clean')

  const files = g.files.map(f =>
    k.item(`file-${f.path}`, {
      lead: 'file',
      leadColor: fileColor(f),
      text: basename(f.path),
      note: dirOf(f.path) || undefined,
      right: [f.kind === 'conflict' ? 'conflict' : f.kind],
    }),
  )

  // ---- pull requests ----
  const prs: (RenderElement | null)[] = []
  if (hub === null || hub.root !== g.root) prs.push(k.note('prs-reading', 'Reading pull requests…', 'loading'))
  else if (hub.note) prs.push(k.note('prs-note', hub.note))
  else if (hub.prs.length === 0) prs.push(k.note('prs-none', 'No open pull requests'))
  else {
    // A PR Workspaces already lists isn't listed again here.
    const listed = new Set(d.branches.map(b => b.pr?.number).filter((n): n is number => n !== undefined))
    const rest = hub.prs.filter(pr => !listed.has(pr.number))
    for (const pr of rest.slice(0, GIT_PRS)) {
      const ci = prChecks(pr)
      prs.push(
        k.item(`pr-${pr.number}`, {
          lead: prIcon(pr),
          leadColor: prColor(pr, false),
          text: pr.title,
          bold: pr.current,
          // Narrow, the number goes before CI: the title already says which PR it is.
          right: [{ part: `#${pr.number}`, drop: 1 }, ci ? k.status(ci[0], ci[1], 'ci') : null],
        }),
      )
      // What else the PR is waiting on, dim, under its title: the failing checks, the review, whether it's this branch's.
      const more = [
        pr.state === 'OPEN' && pr.failing.length ? pr.failing.slice(0, 3).join(', ') : '',
        pr.state === 'OPEN' && pr.isDraft ? 'draft' : '',
        pr.state === 'OPEN' && pr.review === 'APPROVED' ? 'approved' : '',
        pr.state === 'OPEN' && pr.review === 'CHANGES_REQUESTED' ? 'changes requested' : '',
        pr.state === 'OPEN' && pr.review === 'REVIEW_REQUIRED' ? 'review required' : '',
        pr.current ? 'this branch' : '',
      ].filter(Boolean)
      if (more.length) {
        prs.push(
          <Box key={`pr-${pr.number}-more`} paddingLeft={k.edge.left} minWidth={0}>
            <Text dimColor wrap="truncate">
              {more.join(' · ')}
            </Text>
          </Box>,
        )
      }
    }
    if (rest.length > GIT_PRS) prs.push(k.note('prs-more', `… ${rest.length - GIT_PRS} more`))
  }

  return head(k.summary([[g.repo]], state), [
    k.item('git-branch', { lead: GLYPH.branch, text: g.branch, right: sync }),
    k.prop(
      'git-worktree',
      g.worktree.linked ? 'Worktree' : 'Checkout',
      g.worktree.linked ? `${g.worktree.name}, linked (${g.worktree.count} total)` : g.worktree.count > 1 ? `main (+${g.worktree.count - 1} worktrees)` : 'main',
    ),
    <Box key="git-changes" minWidth={0}>
      {changes}
    </Box>,
    ...files,
    g.fileCount > g.files.length ? k.note('git-files-more', `… ${g.fileCount - g.files.length} more`) : null,
    prs.length ? <Box key="git-gap" height={k.space.block} /> : null,
    ...prs,
  ])
}

files.hooks/resources.ts:
import type { Resources } from '../types'

/*
 * The session's share of the machine, from one cheap shell command (ps, sysctl,
 * ioreg, netstat; a few milliseconds): the session's Claude Code process (the
 * nearest ancestor named `claude`), its whole process tree's CPU and memory,
 * and the system's CPU, memory, disk and network. The tree's own network comes
 * from `nettop`, which always takes 5 s (but almost no CPU), on its own. Rates
 * are deltas between samples. macOS only. register.tsx runs the commands; this
 * file parses.
 */

/**
 * The sample command. Measured CPU per run: ps 0.02 s (0.04 s with names, so
 * names only on the first run, to find the session's process), iostat, netstat
 * and sysctl a few ms each.
 */
export const resourcesSh = () => [
  'sh',
  '-c',
  `echo $PPID; ps -A -o pid=,ppid=,%cpu=,rss=${root === null ? ',comm=' : ''}; echo @; sysctl -n hw.ncpu hw.memsize; echo @; ` +
    'iostat -Id -c 1; echo @; netstat -ib',
]

/** The session's Claude Code process, found once. */
let root: number | null = null

/** The tree's network, one nettop sample: per process, bytes in and out so far. */
export const NETTOP = ['nettop', '-P', '-L', '1', '-x', '-J', 'bytes_in,bytes_out']

/** Whether to read the tree's own network with nettop (about 0.015 s of CPU a run). */
export const NET_PER_PROCESS = true

type Counters = { pids: number[]; cores: number; cpu: number; cpuAll: number; mem: number; memAll: number; diskAll: number; netAll: number }

const parse = (out: string): Counters => {
  const [head = '', sys = '', io = '', nets = ''] = out.split('\n@\n')
  const lines = head.split('\n')
  const self = Number(lines[0])
  const rows = new Map<number, { ppid: number; cpu: number; rss: number; name: string }>()
  for (const line of lines.slice(1)) {
    const m = /^\s*(\d+)\s+(\d+)\s+([\d.]+)\s+(\d+)\s*(.*)$/.exec(line)
    if (m) rows.set(Number(m[1]), { ppid: Number(m[2]), cpu: Number(m[3]), rss: Number(m[4]), name: m[5]!.split('/').pop()! })
  }
  // The session's process: the nearest ancestor named `claude`, else the shell's parent.
  if (root === null || !rows.has(root)) {
    root = self
    for (let pid = self; rows.has(pid); pid = rows.get(pid)!.ppid) {
      if (rows.get(pid)!.name === 'claude') {
        root = pid
        break
      }
    }
  }
  const kids = new Map<number, number[]>()
  for (const [pid, r] of rows) kids.set(r.ppid, [...(kids.get(r.ppid) ?? []), pid])
  const pids: number[] = []
  const todo = [root!]
  while (todo.length) {
    const pid = todo.pop()!
    pids.push(pid)
    todo.push(...(kids.get(pid) ?? []))
  }
  const [cores = 1, memAll = 0] = sys.trim().split('\n').map(Number)
  let netAll = 0
  const seen = new Set<string>()
  for (const line of nets.split('\n').slice(1)) {
    const p = line.trim().split(/\s+/)
    if (p.length >= 10 && p[2]!.startsWith('<Link') && !p[0]!.startsWith('lo') && !seen.has(p[0]!)) {
      seen.add(p[0]!)
      netAll += Number(p[6]) + Number(p[9])
    }
  }
  const sum = (f: (r: { cpu: number; rss: number }) => number, ids: Iterable<number>) => [...ids].reduce((n, id) => n + (rows.has(id) ? f(rows.get(id)!) : 0), 0)
  return {
    pids,
    cores,
    cpu: sum(r => r.cpu, pids),
    cpuAll: sum(r => r.cpu, rows.keys()),
    mem: sum(r => r.rss, pids) * 1024,
    memAll,
    // iostat -I: per disk, KB/t, transfers and MB so far; the MB is every third figure.
    diskAll: (io.trim().split('\n').pop() ?? '')
      .trim()
      .split(/\s+/)
      .filter((_, i) => i % 3 === 2)
      .reduce((n, mb) => n + Number(mb) * 1024 * 1024, 0),
    netAll,
  }
}

let prev: { at: number; c: Counters } | null = null
let netPrev: { at: number; bytes: number } | null = null
let net: number | null = null
let treePids: number[] = []

/** Turns one sample into a Resources; null on the first. */
export const toResources = (stdout: string, at: number): Resources | null => {
  const c = parse(stdout)
  treePids = c.pids
  const before = prev
  prev = { at, c }
  if (!before) return null
  const secs = Math.max(0.5, (at - before.at) / 1000)
  const rate = (a: number, b: number) => Math.max(0, (a - b) / secs)
  const allCores = c.cores * 100
  return {
    procs: c.pids.length,
    cpu: (c.cpu / allCores) * 100,
    cpuAll: Math.min(100, (c.cpuAll / allCores) * 100),
    mem: c.mem,
    memAll: c.memAll,
    diskAll: rate(c.diskAll, before.c.diskAll),
    net,
    netAll: rate(c.netAll, before.c.netAll),
  }
}

/** Folds one nettop sample into the tree's network rate. */
export const takeNettop = (stdout: string, at: number) => {
  const mine = new Set(treePids)
  let bytes = 0
  for (const line of stdout.split('\n')) {
    const m = /\.(\d+),(\d+),(\d+),?$/.exec(line)
    if (m && mine.has(Number(m[1]))) bytes += Number(m[2]) + Number(m[3])
  }
  if (netPrev) net = Math.max(0, (bytes - netPrev.bytes) / Math.max(0.5, (at - netPrev.at) / 1000))
  netPrev = { at, bytes }
}

files.kit/skin.ts:
/**
 * A skin: the colours the kit draws with on the app surfaces (desktop, VS Code, mobile), one per
 * meaning (see kit/tokens.ts). Each zen theme pack gives one (kit/skins.ts, made from the pack's
 * palette by zen's `src/harness/claude-code/skins.ts`); a mod wears one with `wear()`.
 *
 * The terminal never draws these values: it draws each meaning in the terminal theme key that
 * means the same thing (THEME_KEY, TERM_TINT in kit/tokens.ts), whatever the skin, so a mod
 * follows the person's terminal theme.
 *
 * Every value is #rrggbb, and every value is its meaning's own: no two meanings share a value,
 * as the terminal finds a meaning by its value. Greys may share one another's.
 */
export type Skin = {
  /** The pack's name, as zen's toolbar shows it. */
  readonly label: string
  /** Finished well: checks passed, an agent done. */
  readonly ok: string
  /** Getting close to a limit: 75% and up, the compaction mark. */
  readonly warn: string
  /** Failed, conflicted, 90% and up. */
  readonly bad: string
  /** Live or in progress: running, pending, the activity series. */
  readonly blue: string
  /** Merged. */
  readonly purple: string
  /** A tint for parts within one chart, never a status. */
  readonly cyan: string
  /** Quantity ink: what a bar or gauge is drawn in when it only says how much. */
  readonly slate: string
  /** A tint for parts within one chart, never a status. */
  readonly orchid: string
  /** Shades within one chart: the live colour and the quantity ink, each base first, then darker, lighter, darkest. */
  readonly ramp: { readonly blue: readonly [string, string, string, string]; readonly slate: readonly [string, string, string, string] }
  /** Text, icons and marks that should recede. */
  readonly muted: string
  /** Text below the main text, each a step quieter. */
  readonly gray: { readonly light: string; readonly mid: string; readonly dark: string }
}

